/* ---- template plumbing: clone a fragment, address its fill-slots ---------- */
var TPL = document.createElement('div');
TPL.innerHTML = TEMPLATE_HTML;
function frag(name) {
  var t = TPL.querySelector('template[data-tpl="' + name + '"]');
  return t.content.firstElementChild.cloneNode(true);
}
function slot(root, name) { return root.querySelector('[data-slot="' + name + '"]'); }
// clone a REAL SCREEN written as plain HTML in template.html (<section data-screen>).
// The logic then fills [data-k]/[data-fill] + wires buttons — HTML is the foundation.
function screen(name) { return TPL.querySelector('[data-screen="' + name + '"]').cloneNode(true); }
function shell(name) { return TPL.querySelector('[data-shell="' + name + '"]').cloneNode(true); }
function fillK(root, k, v) { var n = root.querySelector('[data-k="' + k + '"]'); if (n) n.textContent = String(v); }
// move a screen's element children onto `page` (no wrapper, no whitespace nodes)
// so the final DOM is exactly what the old code produced.
function mountScreen(page, s) { Array.prototype.slice.call(s.children).forEach(function (c) { page.appendChild(c); }); }
// The page-head bar, from the real HTML in template.html instead of the shared
// EPAL.pageHead() builder — same markup, same classes, same one-line <h1> run;
// the title is a TEXT NODE after the icon exactly as pageHead appends it, and
// the sub carries title= so the pinned one-line head stays readable on hover.
function head(o) {
  var h = shell('head');
  h.querySelector('[data-fill="eyebrow"]').textContent = o.eyebrow || '';
  h.querySelector('[data-fill="title"]').appendChild(document.createTextNode(o.title || ''));
  var sub = h.querySelector('[data-fill="sub"]');
  sub.textContent = o.sub || ''; sub.setAttribute('title', o.sub || '');
  var acts = h.querySelector('[data-fill="actions"]');
  (o.actions || []).forEach(function (a) { if (a) acts.appendChild(a); });
  return h;
}

/* reusable markup shells (template.html) — byte-identical to the el() shells they
 * replace. addRow = a primary-action button on its own row; btn/aBtn = a bare
 * button/link; btnStrip = a wrapping flex row; titledCard = card head+sub over a
 * body (the sub span is dropped when empty). */
function addRow(html, onClick) { var r = frag('add-row'); var b = slot(r, 'btn'); b.innerHTML = html; b.addEventListener('click', onClick); return r; }
function btn(cls, html, onClick) { var b = frag('btn'); b.className = cls; b.innerHTML = html; if (onClick) b.addEventListener('click', onClick); return b; }
function aBtn(cls, href, html) { var a = frag('a-btn'); a.className = cls; a.setAttribute('href', href); a.innerHTML = html; return a; }
function btnStrip(children, cls) { var s = frag('btn-strip'); if (cls) s.className = cls; (children || []).forEach(function (c) { if (c) s.appendChild(c); }); return s; }
function sectionLabel(text, extraClass) { var l = frag('section-label'); if (extraClass) l.className += ' ' + extraClass; l.textContent = text; return l; }
function bodyCard(bodyEl) { var c = frag('body-card'); if (bodyEl != null) ui.appendChildren(slot(c, 'body'), bodyEl); return c; }
function titledCard(titleHtml, subText, bodyEl, extraClass) {
  var c = frag('titled-card');
  if (extraClass) c.className += ' ' + extraClass;
  slot(c, 'title').innerHTML = titleHtml;
  var sub = slot(c, 'sub');
  if (subText == null || subText === '') sub.parentNode.removeChild(sub); else sub.textContent = subText;
  if (bodyEl != null) ui.appendChildren(slot(c, 'body'), bodyEl);
  return c;
}

