  var receivable = list.filter(function (s) { return s.kind === 'Receivable' && s.status !== 'Paid'; }).reduce(function (a, s) { return a + (+s.amount || 0); }, 0);
  var overdue = overdueSchedules();
  var soon = dueSoon(7);

